// Validate the app's request (docs/API.md). Bad requests get a 400 with a clear message.
const localIso = (d) => { const p = Object.fromEntries(new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Vancouver',
  year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23',
  timeZoneName: 'longOffset' }).formatToParts(d).map((x) => [x.type, x.value]));
  return `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}:${p.second}${p.timeZoneName.replace('GMT', '') || '+00:00'}`; };
const body = $input.first().json.body || {};
const types = ['pain', 'dose', 'meal', 'walk'];
const isNum = (x) => x !== null && x !== undefined && x !== '' && Number.isFinite(Number(x));
let error = null;
if (!types.includes(body.type)) error = 'type must be one of: pain, dose, meal, walk';
else if (body.type === 'pain' && !(isNum(body.score) && Number.isInteger(Number(body.score)) && body.score >= 0 && body.score <= 10))
  error = 'score must be a whole number from 0 to 10';
else if (body.type === 'walk' && !(isNum(body.minutes) && body.minutes > 0 && body.minutes <= 600))
  error = 'minutes must be a number from 1 to 600';
else if (body.type === 'walk' && body.km !== null && body.km !== undefined && !(isNum(body.km) && body.km >= 0 && body.km < 100))
  error = 'km must be a number, or null for manual walks';
return [{ json: { valid: !error, error, type: body.type, patientId: String(body.patientId || 'P001'), time: localIso(new Date()), body } }];

// Pain log row + the weather right now (Open-Meteo). Weather may be missing; the log is still saved.
const c = $('Check request').first().json;
const w = ($input.first().json || {}).current || {};
return [{ json: { patientId: c.patientId, time: c.time, score: Number(c.body.score), note: String(c.body.note || '').slice(0, 200),
  pressureHpa: w.pressure_msl ?? null, tempC: w.temperature_2m ?? null, precipMm: w.precipitation ?? null } }];

// As-needed dose: the amount always comes from the prescription, never from the app.
const c = $('Check request').first().json;
const rx = $input.all().map((i) => i.json).find((r) => String(r.patientId) === c.patientId);
if (!rx) throw new Error('No prescription for patient ' + c.patientId);
return [{ json: { patientId: c.patientId, time: c.time, mg: Number(rx.doseMg), drug: rx.drug, kind: 'as-needed' } }];

// Walk: GPS walks have km; manual walks send km = null (stored empty). Never coordinates.
const c = $('Check request').first().json;
const km = c.body.km === null || c.body.km === undefined || c.body.km === '' ? null : Math.round(Number(c.body.km) * 100) / 100;
return [{ json: { patientId: c.patientId, time: c.time, km, minutes: Math.round(Number(c.body.minutes)),
  source: c.body.source === 'auto' ? 'auto' : 'manual' } }];

// Built by n8n/build.js from ml/predict.js + n8n/code/check-rules-and-predict.js. Edit those, then rebuild.
// Model weights from ml/weights.json (synthetic, 30 fictional patients, 2036 doses).
const WEIGHTS = {"model":"ridge","target":"hours until pain rises above goal after an as-needed dose","trainedOn":"synthetic, 30 fictional patients, 2036 doses","features":["hour_sin","hour_cos","evening","pain_at_dose","walk_km_prev_3h","walk_min_prev_3h","steps_prev_3h","physio_next_2h","hours_since_scheduled_med","hours_since_meal","pressure_change_6h","temp_c","precip_mm"],"mean":[-0.059298,-0.513844,0.106582,5.969548,0.2039,3.222986,1016.464637,0.02947,5.450388,5.980417,-0.165894,8.042338,0.281434],"scale":[0.746339,0.41883,0.30858,1.440386,0.594858,9.482814,790.233074,0.169119,4.154466,4.366114,3.916826,1.78613,0.719473],"coef":[-0.058907,-0.058552,-0.248723,-0.470103,-0.195391,0.007972,-0.163123,-0.089004,-0.132273,-0.135733,0.288333,-0.036423,-0.089459],"intercept":2.817588,"offsetUpdate":{"keep":0.7,"learn":0.3},"testErrorMin":{"patientMedian":44,"linear":38,"linearPlusOffset":35}};

const TZ = "America/Vancouver";
const MIN_PER_KM = 16;          // average pace: estimates km for manual walks (km = null)
const HOUSEHOLD_STEPS_3H = 750; // steps in 3 h without a walk (no step counter in the app yet)
const STEPS_PER_KM = 1300;

const toDate = (t) => (t instanceof Date ? t : new Date(t));
const hoursBetween = (a, b) => (toDate(b) - toDate(a)) / 3600000;
const isNum = (x) => x !== null && x !== undefined && x !== "" && Number.isFinite(Number(x));

/** Local hour of day (0-24, with minutes) in Vancouver. */
function localHour(t) {
  const parts = new Intl.DateTimeFormat("en-CA", { timeZone: TZ, hour: "numeric", minute: "numeric", hourCycle: "h23" })
    .formatToParts(toDate(t));
  const get = (type) => Number(parts.find((p) => p.type === type).value);
  return get("hour") + get("minute") / 60;
}

/** Hours since the latest event at or before `time`; null if none in the last 24 h (unknown). */
function hoursSinceLast(times, time, cap = 12) {
  const h = times.map((t) => hoursBetween(t, time)).filter((x) => x >= 0 && x <= 24);
  return h.length ? Math.min(cap, Math.min(...h)) : null;
}

/** km for a walk: GPS distance, or estimated from minutes for manual walks (km = null). */
function walkKm(w) {
  return isNum(w.km) ? Number(w.km) : Number(w.minutes || 0) / MIN_PER_KM;
}

/**
 * doseTime:      time of the as-needed dose
 * painAtDose:    pain score at the dose (0-10), or null
 * walks:         [{ time, km|null, minutes }]  (time = walk start)
 * steps:         steps in the 3 h before the dose, or null (estimated from walks)
 * calendar:      [{ start, title }]            (from Google Calendar / schedule table)
 * scheduledMeds: [times]                       (scheduled medication taken)
 * meals:         [times]
 * weather:       { pressureNow, pressure6hAgo, tempC, precipMm } (any may be null)
 */
function buildFeatures({ doseTime, painAtDose = null, walks = [], steps = null, calendar = [],
  scheduledMeds = [], meals = [], weather = {} }) {
  const hour = localHour(doseTime);
  const recent = walks.filter((w) => {
    const end = new Date(toDate(w.time).getTime() + Number(w.minutes || 0) * 60000);
    const h = hoursBetween(end, doseTime);
    return h >= 0 && h < 3; // walk finished in the 3 h before the dose
  });
  const km = recent.reduce((s, w) => s + walkKm(w), 0);
  const physioSoon = calendar.some((e) => /physio/i.test(e.title || "") &&
    hoursBetween(doseTime, e.start) >= 0 && hoursBetween(doseTime, e.start) < 2);
  const w = weather || {};
  return {
    hour_sin: Math.sin((2 * Math.PI * hour) / 24),
    hour_cos: Math.cos((2 * Math.PI * hour) / 24),
    evening: hour >= 18 && hour < 22 ? 1 : 0,
    pain_at_dose: isNum(painAtDose) ? Number(painAtDose) : null,
    walk_km_prev_3h: km,
    walk_min_prev_3h: recent.reduce((s, x) => s + Number(x.minutes || 0), 0),
    steps_prev_3h: isNum(steps) ? Number(steps) : HOUSEHOLD_STEPS_3H + km * STEPS_PER_KM,
    physio_next_2h: physioSoon ? 1 : 0,
    hours_since_scheduled_med: hoursSinceLast(scheduledMeds, doseTime),
    hours_since_meal: hoursSinceLast(meals, doseTime),
    pressure_change_6h: isNum(w.pressureNow) && isNum(w.pressure6hAgo) ? w.pressureNow - w.pressure6hAgo : null,
    temp_c: isNum(w.tempC) ? Number(w.tempC) : null,
    precip_mm: isNum(w.precipMm) ? Number(w.precipMm) : null,
  };
}

/** Global model only (no personal offset). Unknown features count as average (no effect). */
function globalPrediction(weights, features) {
  return weights.features.reduce((h, name, i) => {
    const x = isNum(features[name]) ? Number(features[name]) : weights.mean[i];
    return h + weights.coef[i] * ((x - weights.mean[i]) / weights.scale[i]);
  }, weights.intercept);
}

/** Hours of relief for this patient = global model + their personal offset, kept in a sane range. */
function predictHours(weights, features, offsetHours = 0) {
  const offset = isNum(offsetHours) ? Number(offsetHours) : 0;
  return Math.min(8, Math.max(0.5, globalPrediction(weights, features) + offset));
}

/** B5 learning: after a dose's real relief time is known, nudge the patient's offset. */
function updateOffset(weights, offsetHours, actualHours, features) {
  const { keep, learn } = weights.offsetUpdate || { keep: 0.7, learn: 0.3 };
  const offset = isNum(offsetHours) ? Number(offsetHours) : 0;
  return keep * offset + learn * (actualHours - globalPrediction(weights, features));
}

// B3 · Check rules & predict: the logic of the "Compute status" Code node.
// n8n/build.js pastes this file (plus the helpers from ml/predict.js and ml/weights.json) into the node.
// Test locally: node n8n/test-b3.js
//
// Returns everything GET /dashboard needs (docs/API.md) plus `status` (for the /log reply)
// and `prediction` (for B5 learning / the predictions table).
// Prescription limits are hard rules here. The model never changes them.

function checkRulesAndPredict({ patientId, now, weights, prescription, doses, pain, meals, walks, schedule, patientModel, weatherApi }) {
  const NOW = now ? new Date(now) : new Date();
  const H = 3600000;
  const mine = (rows) => (rows || []).filter((r) => r && String(r.patientId) === String(patientId));
  const byTime = (field) => (a, b) => new Date(a[field]) - new Date(b[field]);
  const upToNow = (field) => (r) => new Date(r[field]) <= NOW;

  // ---------- inputs ----------
  const rx = mine(prescription)[0];
  if (!rx) throw new Error(`No prescription row for patient ${patientId}`);
  const doseMg = Number(rx.doseMg), intervalH = Number(rx.minIntervalH), maxMg = Number(rx.maxMg24h), goal = Number(rx.goal);

  const allDoses = mine(doses).filter(upToNow("time")).sort(byTime("time"));
  const asNeeded = allDoses.filter((d) => !d.kind || d.kind === "as-needed");
  const scheduledMeds = allDoses.filter((d) => d.kind === "scheduled").map((d) => d.time);
  const painLog = mine(pain).filter(upToNow("time")).sort(byTime("time"));
  const mealTimes = mine(meals).filter(upToNow("time")).map((m) => m.time);
  const walkRows = mine(walks).filter(upToNow("time")).sort(byTime("time"));
  const calendar = mine(schedule).sort(byTime("start"));
  const model = mine(patientModel)[0] || { offsetHours: 0, dosesLearned: 0 };

  // ---------- prescription rules ----------
  const doseTimes = asNeeded.map((d) => new Date(d.time).getTime());
  const mgIn24h = (t) => asNeeded.filter((d) => {
    const x = new Date(d.time).getTime();
    return x > t - 24 * H && x <= t;
  }).reduce((s, d) => s + Number(d.mg || doseMg), 0);

  const mgUsed24h = mgIn24h(NOW.getTime());
  const lastDoseAt = doseTimes.length ? doseTimes[doseTimes.length - 1] : null;
  // earliest time that respects BOTH the minimum interval and the 24 h maximum
  let next = Math.max(NOW.getTime(), lastDoseAt === null ? 0 : lastDoseAt + intervalH * H);
  for (let i = 0; i < 50 && mgIn24h(next) + doseMg > maxMg; i++) {
    const inWindow = doseTimes.filter((x) => x > next - 24 * H && x <= next);
    next = inWindow[0] + 24 * H;
  }
  const doseAllowedNow = next <= NOW.getTime();
  const maxReached = mgUsed24h + doseMg > maxMg;

  // ---------- prediction for the last as-needed dose ----------
  let prediction = null;
  if (lastDoseAt !== null) {
    const doseTime = new Date(lastDoseAt);
    const painBefore = painLog.filter((p) => {
      const h = (doseTime - new Date(p.time)) / H;
      return h >= 0 && h <= 1;
    }).pop();
    const features = buildFeatures({
      doseTime,
      painAtDose: painBefore ? painBefore.score : null,
      walks: walkRows,
      calendar,
      scheduledMeds,
      meals: mealTimes,
      weather: weatherAt(weatherApi, doseTime),
    });
    const hours = predictHours(weights, features, model.offsetHours);
    prediction = {
      doseTime: localIso(doseTime),
      predictedHours: round(hours, 2),
      globalHours: round(globalPrediction(weights, features), 2),
      offsetHours: round(Number(model.offsetHours) || 0, 3),
      painLikelyBackAt: localIso(new Date(Math.round((lastDoseAt + hours * H) / 60000) * 60000)),
      features,
    };
  }

  // ---------- patterns (from the patient's own history) ----------
  const reliefHistory = asNeeded.map((d, i) => {
    const t = new Date(d.time).getTime();
    const until = i + 1 < asNeeded.length ? new Date(asNeeded[i + 1].time).getTime() : NOW.getTime();
    const back = painLog.find((p) => {
      const x = new Date(p.time).getTime();
      return x > t && x <= until && Number(p.score) > goal;
    });
    const h = back ? (new Date(back.time).getTime() - t) / H : null;
    return h !== null && h <= 8 ? h : null;
  }).filter((h) => h !== null);
  const reliefHours = reliefHistory.length ? median(reliefHistory) : null;

  const patterns = [];
  if (reliefHours !== null) patterns.push(`Your relief usually lasts about ${round(reliefHours, 1)} hours.`);

  const walkRises = walkRows.filter((w) => walkKm(w) > 1).map((w) => {
    const start = new Date(w.time).getTime();
    const end = start + Number(w.minutes || 0) * 60000;
    const before = painLog.filter((p) => new Date(p.time).getTime() <= start).pop();
    const after = painLog.filter((p) => { const x = new Date(p.time).getTime(); return x > end && x <= end + 2 * H; });
    if (!before || !after.length) return null;
    return Math.max(...after.map((p) => Number(p.score))) - Number(before.score);
  }).filter((x) => x !== null);
  const walkRise = walkRises.length >= 3 ? mean(walkRises) : 0;
  if (walkRise >= 1) patterns.push(`Walks over 1 km raise your pain about ${Math.round(walkRise)} points within 2 hours.`);

  const blocks = [["Mornings (6 AM–12 PM)", 6, 12], ["Afternoons (12–6 PM)", 12, 18], ["Evenings (6–10 PM)", 18, 22]]
    .map(([label, a, b]) => {
      const s = painLog.filter((p) => { const h = localHour(p.time); return h >= a && h < b; }).map((p) => Number(p.score));
      return { label, avg: s.length >= 5 ? mean(s) : null };
    }).filter((x) => x.avg !== null).sort((x, y) => y.avg - x.avg);
  if (blocks.length) patterns.push(`${blocks[0].label} are your hardest time.`);

  const wet = painLog.filter((p) => Number(p.precipMm) > 0).map((p) => Number(p.score));
  const dry = painLog.filter((p) => isNum(p.precipMm) && Number(p.precipMm) === 0).map((p) => Number(p.score));
  if (wet.length >= 5 && dry.length >= 5 && mean(wet) - mean(dry) >= 0.5) {
    patterns.push(`On rainy days your pain is about ${round(mean(wet) - mean(dry), 1)} points higher.`);
  }

  // ---------- heads-ups (never suggest anything outside the prescription) ----------
  const nextDoseAt = new Date(next);
  const headsUps = [];
  const backAt = prediction ? new Date(prediction.painLikelyBackAt) : null;
  if (maxReached) {
    headsUps.push(`You've reached today's maximum (${maxMg} mg). Your next dose is allowed at ${clock(nextDoseAt)}.`);
  }
  if (backAt && backAt > NOW && backAt - NOW <= 90 * 60000) {
    headsUps.push(`Pain likely back around ${clock(backAt)}. Your next dose is allowed ${doseAllowedNow ? "now" : "at " + clock(nextDoseAt)}.`);
  }
  const physio = calendar.find((e) => /physio/i.test(e.title || "") && new Date(e.start) > NOW && new Date(e.start) - NOW <= 3 * H);
  if (physio) {
    headsUps.push(`Physio at ${clock(new Date(physio.start))} (from your calendar). Pain may come back sooner afterwards. ` +
      `Your next dose is allowed ${doseAllowedNow ? "now" : "at " + clock(nextDoseAt)}.`);
  }

  // ---------- output (docs/API.md) ----------
  const last24h = (t) => NOW - new Date(t) <= 24 * H;
  const painNow = painLog.length ? painLog[painLog.length - 1] : null;
  const status = {
    nextDoseAt: localIso(nextDoseAt),
    doseAllowedNow,
    mgUsed24h,
    mgMax24h: maxMg,
    painLikelyBackAt: prediction ? prediction.painLikelyBackAt : null,
  };
  return {
    patientId,
    patient: { name: rx.name, goal, drug: rx.drug, doseMg, minIntervalH: intervalH, maxMg24h: maxMg },
    now: localIso(NOW),
    painNow: painNow ? { score: Number(painNow.score), at: localIso(new Date(painNow.time)) } : null,
    ...status,
    maxReached,
    reliefHours: prediction ? prediction.predictedHours : reliefHours !== null ? round(reliefHours, 1) : null,
    chart: painLog.filter((p) => last24h(p.time)).map((p) => ({ time: localIso(new Date(p.time)), score: Number(p.score) })),
    doses: asNeeded.filter((d) => last24h(d.time)).map((d) => localIso(new Date(d.time))),
    walks: walkRows.filter((w) => last24h(w.time)).map((w) => ({
      time: localIso(new Date(w.time)), km: isNum(w.km) ? Number(w.km) : null, minutes: Number(w.minutes) })),
    patterns,
    headsUps,
    model: {
      type: "personalized ridge regression",
      personalOffsetMin: Math.round((Number(model.offsetHours) || 0) * 60),
      dosesLearnedFrom: Number(model.dosesLearned) || 0,
    },
    status,
    prediction,
  };
}

// ---------- helpers ----------
function weatherAt(api, time) {
  const h = api && api.hourly;
  if (!h || !h.time) return {};
  const idx = (t) => h.time.findIndex((x) => Math.abs(new Date(x + "Z") - t) < 30 * 60000);
  const i = idx(time.getTime()), j = idx(time.getTime() - 6 * 3600000);
  if (i < 0) return {};
  return {
    pressureNow: h.pressure_msl[i],
    pressure6hAgo: j >= 0 ? h.pressure_msl[j] : null,
    tempC: h.temperature_2m[i],
    precipMm: h.precipitation[i],
  };
}
function localIso(d) {
  const parts = Object.fromEntries(new Intl.DateTimeFormat("en-CA", {
    timeZone: TZ, year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit",
    second: "2-digit", hourCycle: "h23", timeZoneName: "longOffset",
  }).formatToParts(d).map((p) => [p.type, p.value]));
  const offset = parts.timeZoneName.replace("GMT", "") || "+00:00";
  return `${parts.year}-${parts.month}-${parts.day}T${parts.hour}:${parts.minute}:${parts.second}${offset}`;
}
function clock(d) {
  return d.toLocaleTimeString("en-US", { timeZone: TZ, hour: "numeric", minute: "2-digit" });
}
function median(a) { const s = [...a].sort((x, y) => x - y); const m = Math.floor(s.length / 2); return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; }
function mean(a) { return a.reduce((s, x) => s + x, 0) / a.length; }
function round(x, n) { const k = 10 ** n; return Math.round(x * k) / k; }


// ---------- run ----------
const input = $('Check request').first().json;
const rows = (node) => $(node).all().map((i) => i.json).filter((r) => r && Object.keys(r).length > 0);
let weatherApi = null;
try { weatherApi = $('Get weather (Open-Meteo)').first().json; } catch (e) { weatherApi = null; }

const result = checkRulesAndPredict({
  patientId: input.patientId || 'P001',
  now: input.now || null,            // demo mode: pass a "pretend now" ISO time
  weights: WEIGHTS,
  prescription: rows('Get prescription'),
  doses: rows('Get doses'),
  pain: rows('Get pain_log'),
  meals: rows('Get meals'),
  walks: rows('Get walks'),
  schedule: rows('Get schedule'),
  patientModel: rows('Get patient_model'),
  weatherApi,
});
return [{ json: result }];

// Reply to the app: { ok, message, warning, status } (docs/API.md). Never suggests a dose outside the prescription.
const c = $('Check request').first().json;
const s = $('Compute status').first().json;
const H = 3600000;
const clock = (t) => new Date(t).toLocaleTimeString('en-US', { timeZone: 'America/Vancouver', hour: 'numeric', minute: '2-digit' });
const SAFETY = "Feeling very drowsy or confused? Don't take more. Call 811 or your care team.";
const next = s.doseAllowedNow ? 'A dose is allowed now.' : 'Your next dose is allowed at ' + clock(s.nextDoseAt) + '.';
let message, warning = null;

if (c.type === 'pain') {
  message = 'Logged pain ' + c.body.score + '/10. ' + next;
  if (Number(c.body.score) >= 9) warning = 'If pain is severe, new, or comes with other symptoms, contact your care team or call 811.';
} else if (c.type === 'dose') {
  // check the dose just saved against the as-needed doses before it
  const t = new Date(c.time).getTime();
  const before = $('Get doses').all().map((i) => i.json)
    .filter((d) => String(d.patientId) === c.patientId && (!d.kind || d.kind === 'as-needed'))
    .map((d) => new Date(d.time).getTime()).filter((x) => x < t - 1000).sort((a, b) => a - b);
  const last = before.length ? before[before.length - 1] : null;
  const tooEarly = last !== null && t - last < s.patient.minIntervalH * H;
  const overMax = s.mgUsed24h > s.mgMax24h;
  message = 'Dose logged (' + s.patient.doseMg + ' mg). ' +
    (s.painLikelyBackAt ? 'Pain likely back around ' + clock(s.painLikelyBackAt) + '. ' : '') + next;
  if (tooEarly || overMax) {
    warning = (tooEarly ? 'This dose was earlier than your prescription allows (every ' + s.patient.minIntervalH + ' h). ' : '') +
      (overMax ? 'You are over your 24 h maximum (' + s.mgMax24h + ' mg). ' : '') + SAFETY;
  }
} else if (c.type === 'meal') {
  message = 'Meal logged. ' + next;
} else {
  const km = c.body.km === null || c.body.km === undefined ? '' : Number(c.body.km).toFixed(1) + ' km, ';
  message = 'Walk logged (' + km + Math.round(c.body.minutes) + ' min). ' + next;
}
return [{ json: { ok: true, message, warning, status: s.status } }];
